import{waveFigure}from './wav1-figures.js?v=20261023-physicscomplete01';
const entries=[['types','Local motion and a travelling wave',['The source creates a disturbance.','A highlighted marker oscillates locally.','The pattern transfers energy along the medium.','The medium does not travel with every crest.']],['properties','Trace wave quantities',['Identify equilibrium and amplitude.','Adjacent matching phase points define wavelength.','Repeated cycles define frequency and period.','Wave speed equals frequency times wavelength.']],['reflection','A reflected ray',['An incoming ray approaches a boundary.','Measure incidence from the normal.','The wave reflects into the first medium.','Reflection angle equals incidence angle.']],['sound','A local sound disturbance',['Sound pressure varies.','Particles oscillate around local positions.','A solid membrane can be driven to vibrate.','Conversions operate over a limited frequency range.']],['detection','An echo returns from a boundary',['Emit a pulse.','Travel to a hidden boundary.','Part of the disturbance reflects.','The detector records an out-and-back time.']],['spectrum','EM energy transfer',['A source creates an electromagnetic disturbance.','A transverse pattern transfers energy.','All bands share the same vacuum speed.','An absorber can receive the transferred energy.']],['refraction','A ray crosses into a slower medium',['The incident ray approaches obliquely.','Mark the boundary normal.','Speed changes in the second medium.','The transmitted direction bends toward the normal.']],['lenses','Converging rays form a real image',['Light leaves the object.','One representative ray travels parallel to the axis.','The lens refracts it toward the focus.','Rays meet at a real inverted image.']],['blackbody','Compare thermal spectra',['A cooler object emits radiation.','A hotter object emits more power.','The emission peak moves to shorter wavelength.','The curves illustrate a temperature-dependent distribution.']]];
export const wav1Films=Object.fromEntries(entries.filter(([k])=>!['lenses','blackbody'].includes(k)).map(([k,title,steps])=>['wav1-'+k,{title,steps,duration:16,render:p=>waveFigure({kind:k,movie:true,progress:p,...(k==='sound'?{a:'longitudinal'}:{})}),note:'Original schematic. Local particle oscillation is distinguished from travelling wave patterns; real water-surface particle paths are more complex. Playback is slowed independently of numerical SI quantities. Ray angles and spectra are illustrative; no measured optical constants or clinical signals are inferred. Echo depth assumes one boundary and a homogeneous medium. Constrained ray/graph tasks and generated data do not establish freehand construction or physical practical competence.'}]));
